// 只声明原收帖人的固定答复与有限原节点路径；未知/歧义/自动业务节点一律拒绝。
#include "visit_reply_intents.hpp"
#include "visit_reply_detail.hpp"
#include "visit_reply_boundary.hpp"
#include <set>
namespace hanmo::resident {namespace {
void unique(const BoundaryValue& v,const StableId& path){std::set<StableId> keys;for(const auto& f:boundary::object(v,path))if(!keys.insert(f.first).second)boundary::fail("DuplicateVisitReplyIntentField",path);}
const DialogueNode* node(const DialogueDefinition& d,const StableId& id){const DialogueNode* found=nullptr;for(const auto& n:d.nodes)if(n.id==id){if(found)return nullptr;found=&n;}return found;}
}
const VisitReplyIntent* visit_reply_intent(const VisitReplyIntentCatalog& c,const StableId& id){for(const auto& i:c.intents)if(i.id==id)return &i;return nullptr;}
const VisitReplyIntent* visit_reply_reception_intent(const VisitReplyIntentCatalog& c,const StableId& id){for(const auto& i:c.intents)if(i.reception_intent_id==id)return &i;return nullptr;}
Status validate_visit_reply_intents(const VisitReplyIntentCatalog& c,const VisitReplyCatalog& replies,const VisitReceptionCatalog& reception,const VisitMessageCatalog& messages,const InteractionCatalog& interactions){
    auto valid=validate_visit_reception_catalog(reception,messages,interactions);if(!valid.ok)return valid;valid=validate_visit_reply_catalog(replies,messages,interactions);if(!valid.ok)return valid;
    if(c.version!=1||!visit_reply_authored_version(replies.version)||c.intents.empty()||c.intents.size()>4096)return common_failure("VisitReplyIntentProfileRequired");std::set<StableId> ids,originals;
    for(const auto& i:c.intents){const auto* r=visit_reception_intent(reception,i.reception_intent_id);const auto* p=visit_reply_detail::policy(replies,i.reply_policy_id);const auto* m=p?visit_reply_detail::original(messages,p->message_policy_id):nullptr;
        if(i.id.empty()||i.id.size()>256||!ids.insert(i.id).second||!originals.insert(i.reception_intent_id).second||!r||r->purpose!="receive"||!m||r->message_policy_id!=p->message_policy_id||r->actor_id!=m->recipient_actor_id||(i.response!="declined"&&i.response!="contact_in_person")||i.route.empty()||i.route.size()>16)return common_failure("InvalidVisitReplyIntent",i.id);
        const DialogueDefinition* d=nullptr;for(const auto& item:interactions.dialogues)if(item.id==m->dialogue_id)d=&item;if(!d)return common_failure("InvalidVisitReplyIntentDialogue",i.id);
        for(const auto& step:r->route){const auto* original_node=node(*d,step.node_id);if(!original_node||original_node->command)return common_failure("VisitReplyUnsafeIntentRoute",i.id);}
        StableId current=m->receive_node_id;std::set<StableId> seen;
        for(const auto& step:i.route){const auto* n=node(*d,current);if(!n||n->command||current==p->reply_node_id||step.node_id!=current||!seen.insert(current).second)return common_failure("InvalidVisitReplyIntentRoute",i.id);
            if(n->kind=="say"){if(!step.option_id.empty()||n->next.empty())return common_failure("InvalidVisitReplyIntentRoute",i.id);current=n->next;}
            else if(n->kind=="choice"){const DialogueOption* option=nullptr;for(const auto& o:n->options)if(o.id==step.option_id){if(option)return common_failure("InvalidVisitReplyIntentRoute",i.id);option=&o;}if(!option||option->next.empty())return common_failure("InvalidVisitReplyIntentRoute",i.id);current=option->next;}
            else return common_failure("VisitReplyUnsafeIntentRoute",i.id);
        }
        if(current!=p->reply_node_id||seen.count(current))return common_failure("VisitReplyIntentDeclarationUnreachable",i.id);
    }return common_success();
}
Outcome<VisitReplyIntentCatalog> decode_visit_reply_intents(const BoundaryValue& v,const VisitReplyCatalog& replies,const VisitReceptionCatalog& reception,const VisitMessageCatalog& messages,const InteractionCatalog& interactions){try{
    using namespace boundary;unique(v,"visit_reply_intents");fields(v,{"version","intents"},{},"visit_reply_intents");VisitReplyIntentCatalog c;c.version=get_int(v,"version","visit_reply_intents");const auto& rows=array(field(v,"intents","visit_reply_intents"),"intents");if(rows.size()>4096)fail("VisitReplyIntentLimit","intents");
    for(const auto& row:rows){unique(row,"intent");fields(row,{"id","reception_intent_id","reply_policy_id","response","route"},{},"intent");VisitReplyIntent i;i.id=get_string(row,"id","intent");i.reception_intent_id=get_string(row,"reception_intent_id","intent");i.reply_policy_id=get_string(row,"reply_policy_id","intent");i.response=get_string(row,"response","intent");const auto& route=array(field(row,"route","intent"),"route");if(route.size()>16)fail("VisitReplyIntentRouteLimit",i.id);for(const auto& row:route){unique(row,"step");fields(row,{"node_id"},{"option_id"},"step");VisitReceptionStep step;step.node_id=get_string(row,"node_id","step");if(row.find("option_id"))step.option_id=get_string(row,"option_id","step");i.route.push_back(std::move(step));}c.intents.push_back(std::move(i));}
    auto valid=validate_visit_reply_intents(c,replies,reception,messages,interactions);return valid.ok?Outcome<VisitReplyIntentCatalog>{true,std::move(c),{}}:Outcome<VisitReplyIntentCatalog>{false,{},valid.error};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_visit_reply_intents(const VisitReplyIntentCatalog& c){using V=BoundaryValue;V::Array rows;for(const auto& i:c.intents){V::Array route;for(const auto& step:i.route){auto row=boundary::obj({{"node_id",V{step.node_id}}});if(!step.option_id.empty())row.as<V::Dict>()->emplace_back("option_id",V{step.option_id});route.push_back(std::move(row));}rows.push_back(boundary::obj({{"id",V{i.id}},{"reception_intent_id",V{i.reception_intent_id}},{"reply_policy_id",V{i.reply_policy_id}},{"response",V{i.response}},{"route",V{std::move(route)}}}));}return boundary::obj({{"version",V{c.version}},{"intents",V{std::move(rows)}}});}
Outcome<Integer> decode_visit_reply_profile_version(const BoundaryValue&scenario,const std::vector<StableId>&caps){try{using namespace boundary;unique(scenario,"scenario");const auto*p=scenario.find("visit_reply_profile"),*catalog=scenario.find("visit_message_replies"),*intents=scenario.find("visit_reply_intents");if(!p){if(catalog||intents)unsupported("VisitReplyProfileRequired","visit_reply_profile");return {true,0,{}};}const auto name=string(*p,"visit_reply_profile");const Integer version=name=="witnessed_visit_replies_v1"?1:name=="witnessed_authored_visit_replies_v2"?2:name=="witnessed_visit_replies_life_v3"?3:name=="witnessed_authored_visit_replies_life_v4"?4:0;if(!version)unsupported("UnsupportedVisitReplyProfile","visit_reply_profile");if(!catalog||get_int(*catalog,"version","visit_message_replies")!=version)unsupported("VisitReplyCatalogVersionMismatch","visit_message_replies");if(bool(intents)!=visit_reply_authored_version(version))unsupported("VisitReplyIntentProfileRequired","visit_reply_intents");auto messages=decode_visit_message_profile_version(scenario,caps);if(!messages.ok)return {false,{},messages.error};if(visit_reply_life_version(version)?(messages.value<2||messages.value>3):messages.value!=1)unsupported("VisitReplyOriginalProfileRequired","visit_message_profile");auto required=[&](const char*cap){if(std::find(caps.begin(),caps.end(),cap)==caps.end())unsupported("VisitReplyCapabilityRequired",cap);};required("visit_message_replies_v1");if(visit_reply_authored_version(version)){required("visit_message_replies_v2");auto reception=decode_visit_reception_profile(scenario,caps);if(!reception.ok)return {false,{},reception.error};if(!reception.value)unsupported("VisitReceptionProfileRequired","visit_reply_profile");}if(visit_reply_life_version(version))required(version==3?"visit_message_replies_v3":"visit_message_replies_v4");return {true,version,{}};}catch(const boundary::DecodeFailure&e){return {false,{},e.error};}}
}
